package com.saludintegral.paciente.controller;
import org.springframework.web.bind.annotation.*; import org.springframework.http.*; import jakarta.validation.Valid; import java.util.*; import com.saludintegral.paciente.model.Paciente; import com.saludintegral.paciente.dto.PacienteRequest; import com.saludintegral.paciente.services.PacienteService;
@RestController @RequestMapping("/api/pacientes") public class PacienteController {final PacienteService s; public PacienteController(PacienteService s){this.s=s;} @GetMapping public List<Paciente> all(){return s.all();} @GetMapping("/{id}") public Paciente get(@PathVariable Long id){return s.get(id);} @PostMapping public ResponseEntity<Paciente> create(@Valid @RequestBody PacienteRequest x){return ResponseEntity.status(201).body(s.save(x));} @PutMapping("/{id}") public Paciente update(@PathVariable Long id,@Valid @RequestBody PacienteRequest x){return s.update(id,x);} @DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();} }
